def preserve_latest_sensor_receipt(apps, schema_editor):
    Device = apps.get_model('iot', 'Device')
    SensorData = apps.get_model('iot', 'SensorData')
    SensorReading = apps.get_model('iot', 'SensorReading')
    for device in Device.objects.all().iterator():
        reading_time = SensorReading.objects.filter(device_id=device.pk).order_by(
            '-received_at').values_list('received_at', flat=True).first()
        legacy_time = SensorData.objects.filter(device_id=device.pk).order_by(
            '-timestamp').values_list('timestamp', flat=True).first()
        candidates = [value for value in (reading_time, legacy_time) if value is not None]
        if candidates:
            Device.objects.filter(pk=device.pk).update(
                last_sensor_received_at=max(candidates))


